CREATE TABLE IF NOT EXISTS gis_canonical_admin_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL, admin_level text NOT NULL, canonical_code text NOT NULL, canonical_name text NOT NULL, parent_canonical_code text, source_authority text NOT NULL, source_version text, status text NOT NULL DEFAULT 'Proposed', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_code,admin_level,canonical_code));
CREATE TABLE IF NOT EXISTS gis_identity_review_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES gis_spatial_identity_matches(id) ON DELETE CASCADE, decision text NOT NULL, selected_target_feature_id text, reviewer_id text, rationale text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_canonical_admin ON gis_canonical_admin_identities(country_code,admin_level,canonical_code);
CREATE INDEX IF NOT EXISTS idx_gis_identity_review ON gis_identity_review_decisions(match_id,decision);